export const EVENTS=Object.freeze([{id:"easy",label:"Easy",blurb:"Against the three slowest cars in the hall"},{id:"medium",label:"Medium",blurb:"Against three cars from the middle of the pack"},{id:"hard",label:"Hard",blurb:"Against the three fastest, last year’s champion among them"},{id:"trial",label:"Time Trial",blurb:"Your own cars against each other, or one alone"},{id:"outlaw",label:"Outlaw exhibition",blurb:"An Outlaw car against the three fastest, marked as an exhibition"}]),CHALLENGE=Object.freeze({event:"Head to head",blurb:e=>`Your car against ${e}: four heats, each car in every lane`,invite:(e,t)=>e?`${e} has challenged you to a race against ${t}!`:`A friend has challenged you to a race against ${t}!`,inviteMore:"Choose your car and press Go, or tune it at the workbench first.",bad:"That challenge link did not come through whole, so here is your workbench instead. Ask your friend to send it again.",heading:"How the two cars compared",won:(e,t)=>`You beat ${e} by ${t} seconds!`,lost:(e,t)=>`${e} wins by ${t} seconds.`,tie:(e,t)=>`A dead heat with ${e}! Both cars averaged ${t} seconds, to the timer’s finest reading, so you share the win.`,alike:"Nothing separated them: the two cars ran exactly alike.",boardWon:(e,t,a)=>`Tied with ${e} at ${t} seconds on the board! The timer’s finer reading gave it to you, by ${fineWords(a)}.`,boardLost:(e,t,a)=>`Tied with ${e} at ${t} seconds on the board! The timer’s finer reading gave it to them, by ${fineWords(a)}.`,theirEdge:(e,t)=>`The biggest difference was their ${e}. On your car, it would be worth about ${t} seconds.`,yourEdge:(e,t)=>`Your ${e} made the biggest difference, worth about ${t} seconds on their car.`,even:"Your axles were tuned alike, so the difference was in the shapes and the weights.",send:"Challenge a friend",sendBack:"Send a challenge back",title:"Challenge a friend",text:e=>`Send ${e} to a friend. They race their own car against it, head to head.`,fromLabel:"Your first name (optional)",share:"Send the challenge",copy:"Copy the link",done:"Done",note:"The link holds your car and the name you type, nothing else. Nothing is uploaded.",shareText:(e,t,a)=>e?`${e} challenges you to a derby race! Can your car beat ${t}? It averaged ${a} seconds at Derby Day.`:`Can your derby car beat ${t}? It averaged ${a} seconds at Derby Day.`,shared:"Sent. Good luck to them!",copied:"The link is copied. Paste it into a message to a friend.",manual:"Copy the link below and paste it into a message to a friend."});export function edgeWords(e){return e?e.id==="polish"?`axles polished to ${POLISH[e.level]}`:{deburr:"de-burred axles",graphite:"graphite on the axles",align:"aligned wheels",sand:"sanded edges"}[e.id]||"":""}export const HARDER=Object.freeze({easy:"medium",medium:"hard"}),UI=Object.freeze({title:"DERBY DAY",subtitle:"Race a wooden derby car down a four-lane track",raceLegend:"Your race",carLegend:"Your car",carsLegend:"Your cars, up to four",go:"Go!",pickOne:"Please pick at least one car for the Time Trial.",tooMany:"The track has four lanes, so four cars at most.",skip:"Skip to results",you:"You",replay:"Slow motion",photo:"Photo finish",resultsTitle:"Results",raceAgain:"Race again",another:"Choose another race",lanesHeading:"Each lane’s average",whyHeading:"Why your car ran as it did",trialHeading:"How your cars compared",place:"Place",car:"Car",average:"Average",heats:"Heats",seconds:"seconds",benchTitle:"Your workbench",raceIt:"Race it",toBench:"Back to the workbench",tune:"Tune my car",garage:"Your garage",newCar:"New car",copyCar:"Copy this car",deleteCar:"Delete this car",shape:"Shape",paint:"Paint",bodyColor:"Body",stripe:"Stripe",noStripe:"No stripe",customColor:"Custom color",finish:"Finish",weights:"Weights",autoWeigh:"Auto-weigh",allOut:"Take them all out",takeOut:"Take out",front:"Front",rear:"Rear",axleMark:"Axle",axles:"Axles and wheels",rules:"Rules",standard:"Standard",standardBlurb:"The house rule sheet: 5 ounces, the kit’s wheels and axles",outlaw:"Outlaw",outlawBlurb:"No rule sheet, only what the track allows. Races the Time Trial and the Outlaw exhibition",alsoMeasured:"Also measured",settings:"Settings",units:"Units",forget:"Forget my cars",forgetSure:"Tap again to forget every car, result and trophy",explore:"More 3D worlds to explore at SceneXP.com",trophies:"Trophies",noTrophies:"No trophies yet. Win a division to put one on the shelf.",drawOwn:"Or draw your own",view:"Look at it",fromSide:"From the side",fromAbove:"From above",carveHelp:"Drag a point up or down, or tab to it and use the arrow keys. The points beside the axles keep enough wood to hold them. The drawing is twice as tall as the block so there is room to work, and the turntable shows it true.",cut:"Cut along the line",rubOut:"Rub out the line",sand:"Sand the edges",livery:"Decals and name",carName:"Its name, on both sides",carNumber:"Its number, on the nose",decals:"Decals",addDecal:"Stick it on",onTheCar:"On the car",along:"Along the car",upDown:"Up and down",size:"Size",peel:"Peel it off",doDeburr:"File off the burrs",doGraphite:"Puff in graphite",doAlign:"Roll it and align it",freshAxles:"Fresh axles from the kit",tuneHelp:"One tap a step. Each one shows what it does, and the host says what it was worth on the track.",tuneupsHeading:"What each tune-up was worth",skipWeighIn:"Skip the weigh-in",weighInBack:"Back to the workbench",family:"Your family",dressing:"Dressing",grownUp:"The grown-up",kid:"The kid",shirt:"Shirt",pants:"Pants",skin:"Skin tone",hairColor:"Hair color",hairLength:"Hair"}),CALLS=Object.freeze({off:Object.freeze(["And they’re off!","There goes the gate!","Off they go!","Here they come, one last time!"]),lead:e=>`${e} out in front!`,leadMine:e=>`${e} out in front, and the family is on its feet!`,close:(e,t,a)=>`By a nose! ${t} takes heat ${e} in ${clock(a)} seconds.`,photo:(e,t)=>`Photo finish! ${e} by ${gapWords(t)}.`,weighIn:"Cars to the registration table, please.",dance:(e,t,a)=>a?`${e} wins the day, and your family breaks out ${t}!`:`${e} wins the day, and here comes ${t}!`});export function fineWords(e){return e<5e-5?"less than a ten-thousandth of a second":`${e.toFixed(4)} seconds`}export function tiedPlace(e){return`${placeWord(e)} (tie)`}export function tieLine({dead:e,by:t},a,r,i,h){return e?`A dead heat! ${a} and ${r} both averaged ${i} seconds, to the timer’s finest reading, so they share ${placeWord(h)} place.`:`Tied at ${i} seconds on the board! The timer’s finer reading gave ${placeWord(h)} place to ${a}, by ${fineWords(t)}.`}export function gapWords(e){return e<5e-4?"less than a thousandth of a second":`${clock(e)} seconds`}export function gateCall(e,t){return e===t?CALLS.off[3]:CALLS.off[(e-1)%3]}export function polishButton(e){return["Polish with 400 grit","Polish with 800 grit","Polish with 1200 grit","Polish with 2000 grit","Polish with compound"][e]||""}export const SAND=Object.freeze(["Square, as cut","Lightly sanded","Softened","Rounded","Well rounded"]);export function eventLabel(e){if(e==="challenge")return CHALLENGE.event;const t=EVENTS.find(a=>a.id===e);return t?e==="trial"||e==="outlaw"?t.label:`${t.label} division`:""}export const POLISH=Object.freeze(["Not polished","400 grit","800 grit","1200 grit","2000 grit","2000 grit and polishing compound"]);export function clock(e){return e.toFixed(3)}export function placeWord(e){const t=e%100;return t>=11&&t<=13?`${e}th`:`${e}${["th","st","nd","rd"][e%10]||"th"}`}export function heatOf(e,t){return`Heat ${e} of ${t}`}export function staging(e,t){return e===1?"Cars on the track. Lane 4 runs a hair slow, so every car will race in every lane.":e===t?"The last heat. One more lane each.":`Heat ${e}. Every car moves over one lane.`}export const OFF="And they’re off!",COUNT=Object.freeze({go:"Go!",spoken:(e,t)=>`${heatOf(e,t)} starts in 3 seconds.`});export function heatWinner(e,t,a){return`${t} takes heat ${e} in ${clock(a)} seconds.`}export function heatSpoken(e,t){const a=t.map(r=>`${r.name} ${placeWord(r.place)}, ${clock(r.time)} seconds`);return`Heat ${e}: ${a.join(". ")}.`}export function resultsSpoken(e,t){const a=t.map(r=>`${placeWord(r.place)}${r.tied?", tied":""}, ${r.name}, averaging ${clock(r.average)} seconds`);return`${eventLabel(e)} results. ${a.join(". ")}.`}const o=e=>`${clock(e)} seconds`,c=5e-4;export function carveLine(e){return`Weight further back would save ${o(e)}, but this body has no room for it there. Carve some wood out of the middle and the weights can sit further back.`}export function moreLine(e,t,a,{maxMass:r="5 ounces",idealText:i="three quarters of an inch",bulky:h=!1}={}){const s=e.more,l=t.balance>a;if(e.id==="balance"&&l&&h)return carveLine(s);switch(e.id){case"weight":return`Weights up to the full ${r} would save ${o(s)}.`;case"balance":return l?`Moving the weight back, to about ${i} in front of the rear axle, would save ${o(s)}.`:`Moving the weight forward a little, to about ${i} in front of the rear axle, would save ${o(s)}.`;case"axles":return`Polished axles and graphite would save ${o(s)}.`;case"alignment":return`Aligning the wheels would save ${o(s)}.`;default:return`A slimmer shape would save ${o(s)}.`}}export function gains(e){return e.lines.filter(t=>t.more>c).sort((t,a)=>a.more-t.more)}export function whyLines(e,t,a,r={}){const i=e.lines.filter(n=>n.saved!==null&&n.saved>c).sort((n,g)=>g.saved-n.saved),h=gains(e),s=[],l={weight:n=>`Its extra weight was worth ${o(n)} over the kit’s own weight.`,balance:n=>`Weight toward the back was worth ${o(n)} over a car balanced in the middle.`,axles:n=>`The work on its axles was worth ${o(n)}.`,alignment:n=>`Straight wheels were worth ${o(n)}.`,shape:n=>`Its shape was worth ${o(n)} over a plain block.`};i.length&&s.push(l[i[0].id](i[0].saved));const d=h.slice(0,2);for(const n of d)s.push(moreLine(n,t,a,r));const u=h.find(n=>n.id==="balance");return r.bulky&&u&&t.balance>a&&!d.includes(u)&&s.push(carveLine(u.more)),(!h.length||h[0].more<.002)&&s.push("There is very little left to find. This car is about as fast as the rules allow."),s}export function trialLines(e){if(e.length===1)return[`${e[0].name} averaged ${o(e[0].average)} over the four lanes.`];const t=[];for(let a=1;a<e.length;a++){const r=e[a].average-e[a-1].average;t.push(r>c?`${e[a-1].name} beat ${e[a].name} by ${o(r)}.`:`${e[a-1].name} and ${e[a].name} tied.`)}return t}export const FIX_SECTION=Object.freeze({weight:"weights",balance:"weights",axles:"axles",alignment:"axles",shape:"shape"});const w=Object.freeze({weights:"Weights",axles:"Axles and wheels",shape:"Shape"});export function hostFirst(e,t){return`Welcome to Derby Day! This is your car, ${e}, already weighed to ${t}. Choose a shape and a color, then race it whenever you’re ready.`}export function hostBack(e,t){if(!t)return`Welcome back! ${e} is on the bench, ready when you are.`;if(t.event==="trial")return`Welcome back! ${e} averaged ${o(t.average)} in the Time Trial. Would you like to tune it, or race again?`;const a=t.event==="outlaw"?"the Outlaw exhibition":`the ${eventLabel(t.event)}`;return`Welcome back! Your car, ${e}, finished ${placeWord(t.place)} in ${a}. Would you like to tune it, or race again?`}export function hostStep(e){return`Here’s ${e} on the bench, ready for another change or another race.`}export function hostTune(e,t,a){return!t||t.more<.002?`Here’s ${e} back on the bench. It’s about as fast as the rules allow. Try a harder race, or build a second car to compare in the Time Trial.`:`Here’s ${e} back on the bench. ${a} You’ll find that under ${w[FIX_SECTION[t.id]]}.`}export const SAY=Object.freeze({autoWeighed:(e,t)=>`Auto-weigh brought it to ${e}, the weight ${t} in front of the rear axle. Weight toward the back keeps the car higher on the slope for longer, so it has further to fall.`,autoShort:(e,t)=>`Auto-weigh did what this shape allows: ${e}, the weight ${t} in front of the rear axle. A bulky body has no room further back, but carving wood out of the middle would make some.`,allOut:e=>`Every weight is out. The car weighs ${e} now.`,shapeAuto:e=>`A ${e} now, and Auto-weigh moved the weights to suit it.`,shapeHand:(e,t)=>t?`A ${e} now. ${t===1?"One weight no longer fits, so it’s":`${t} weights no longer fit, so they’re`} back in the box.`:`A ${e} now. Every weight still fits.`,outlaw:e=>`Outlaw class. The rule sheet is off, so the weight can go up to ${e}, the most the track will take. Outlaw cars race in the Time Trial and the Outlaw exhibition.`,standard:e=>`Standard class: ${e} at most, and the house rule sheet.`,noWood:"There isn’t enough wood there for a pocket.",full:"That pocket is full.",stripsFull:"Two strips is all that spot takes.",empty:"That pocket is already empty.",newCar:(e,t)=>`A new car on the bench: ${e}, weighed to ${t}. Your other cars wait in the garage.`,copied:(e,t)=>`A copy of ${e}, called ${t}. Change one thing, then race the two in the Time Trial to see what it was worth.`,full4:"The garage holds four cars. Please delete one to make room.",deleteSure:e=>`Tap Delete again to remove ${e}.`,deleted:(e,t)=>`${e} is gone. ${t} is on the bench now.`,picked:e=>`${e} is on the bench.`,forgetSure:"Tap Forget again to clear every car, result and trophy from this browser.",forgot:e=>`Everything is forgotten. Here’s a fresh car to start with, ${e}.`,cutting:"Cutting along your line…",cutAuto:e=>`Cut! Auto-weigh moved the weights to suit the new shape, ${e} in all.`,cutHand:(e,t)=>e?`Cut! ${e===1?"One weight lost its pocket, so it’s":`${e} weights lost their pockets, so they’re`} back in the box. The car weighs ${t} now.`:`Cut! Every weight still has its pocket. The car weighs ${t} now.`,sanded:e=>`Sanded: ${e.toLowerCase()}. Rounder edges let the air slip past a little more easily, and the wood that came off came off the weight.`,decalsFull:"That’s as many decals as a car this size can wear. Please peel one off to make room.",decalOn:e=>`${e} stuck on. Move it with the sliders, or drag it on the picture.`,decalOff:e=>`${e} peeled off.`,deburred:e=>`The burrs are filed off every axle. That’s worth ${o(e)} on the track.`,polished:(e,t)=>`Polished with ${e}. That’s worth ${o(t)} more.`,graphited:e=>`A puff of graphite in every wheel, spun to work it in. That’s worth ${o(e)}.`,aligned:e=>`It drifted toward the rail, so the axles were tapped straight. Now it rolls true, worth ${o(e)}.`,fresh:"Fresh axles from the kit, burrs, crimp marks and all, and the wheels as they go on."});export function tuneupLines(e){const t=[];for(const a of e)a.id==="deburr"&&t.push(a.done?`De-burred axles: worth ${o(a.saved)}.`:`Filing off the burrs would save ${o(a.more)}.`),a.id==="polish"&&(a.done?a.more>c?t.push(`Axles polished to ${POLISH[a.level]}: worth ${o(a.saved)}. Polishing on through the compound would save ${o(a.more)} more.`):t.push(`Axles polished through the compound: worth ${o(a.saved)}.`):t.push(`Polishing the axles would save ${o(a.more)}.`)),a.id==="graphite"&&t.push(a.done?`Graphite in the wheels: worth ${o(a.saved)}.`:`A puff of graphite would save ${o(a.more)}.`),a.id==="align"&&t.push(a.done?`Straight wheels: worth ${o(a.saved)}.`:`Aligning the wheels would save ${o(a.more)}.`);return t}export const WEIGH=Object.freeze({onScale:e=>`${e} on the scale…`,reading:e=>`${e} on the scale.`,gauge:"Through the gauge box…",passed:e=>`${e} passes the weigh-in. Good luck!`,over:(e,t)=>`${e} weighs in ${t} over the limit, so it can’t race just yet. Please take a weight out on the bench and come back.`,shape:(e,t)=>`${e} won’t pass the gauge box: ${t} Please fix it on the bench and come back.`,sentBack:(e,t)=>`The weigh-in sent ${e} back to the bench. ${t}`,spoken:(e,t,a)=>a?`${e} weighs ${t} and passes the gauge box.`:`${e} does not pass the weigh-in.`});export function ruleNote(e,t){switch(e){case"mass":return`${t} over. Please take a weight out.`;case"length":return`${t} too long.`;case"width":return`${t} too wide.`;case"wheelGap":return`${t} too narrow between the wheels.`;default:return`${t} too low to the track.`}}export const RULE_NAMES=Object.freeze({mass:"Weight",length:"Length",width:"Width",wheelGap:"Between the wheels",clearance:"Ground clearance"}),ENTRY=Object.freeze({outlawOnly:"Outlaw cars race in the Time Trial and the Outlaw exhibition.",standardOnly:"The Outlaw exhibition is for Outlaw cars. Switch a car to Outlaw on the bench.",illegal:"Over the rule sheet’s limits, so the weigh-in will hand it back.",noneEligible:"None of your cars can enter this race yet. The bench can change that.",benchFirst:"Please fix your car on the bench first."});export function trophyLine(e,t){const a=e==="outlaw"?"the Outlaw exhibition":`the ${eventLabel(e)}`;return t?`First place! A trophy for ${a} is waiting on your workbench shelf.`:`First place in ${a} again!`}export function harderLabel(e){return HARDER[e]?`Try the ${eventLabel(HARDER[e])}`:""}export function trophyList(e){const t=["easy","medium","hard","outlaw"].filter(a=>e[a]).map(a=>a==="outlaw"?"Outlaw exhibition":EVENTS.find(r=>r.id===a).label);return t.length?`${UI.trophies}: ${t.join(", ")}.`:UI.noTrophies}export function bestLine(e,t){const a=[];for(const r of["easy","medium","hard","outlaw"]){const i=t[r];i&&i.place&&a.push(`${placeWord(i.place)} in ${r==="outlaw"?"the Outlaw exhibition":eventLabel(r)}`)}return t.trial&&a.push(`${o(t.trial.average)} in the Time Trial`),a.length?`${e}’s best: ${a.join(", ")}.`:`${e} hasn’t raced yet.`}export function sheetLines(e,t,a){return e==="outlaw"?{title:"OUTLAW CLASS",lines:["No rule sheet. Only the track:",`Weight: up to ${a.mass(t.maxMass)}`,`Fits the lane: ${a.length(t.maxWidth)} wide`,`Clears the center strip: ${a.length(t.minWheelGap)}`,"Four wheels on the track"]}:{title:"HOUSE RULES",lines:[`Weight: ${a.mass(t.maxMass)} at most`,`Length: ${a.length(t.maxLength)} at most`,`Width: ${a.length(t.maxWidth)} at most`,`Between the wheels: ${a.length(t.minWheelGap)}`,`Ground clearance: ${a.length(t.minClearance)}`,"The kit’s own wheels and axles","Dry graphite only"]}}
